import{_ as s,C as t,o as i,c as o,E as a,a2 as d}from"./chunks/framework.BOeh4kYD.js";const c="/joinwell52/assets/execution-facts-20260915/pause-is-not-failure.figure.en.svg",w=JSON.parse('{"title":"Why did pausing work turn into a task failure?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Why did pausing work turn into a task failure?","date":"2026-09-15","published_date":"2026-09-15","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Why did pausing work turn into a task failure?","summary":"Pause should mean wait a while. Why did tasks still need intervention after resuming? The problem began when “cannot continue” lost its reason.","cover":"/assets/execution-facts-20260915/pause-is-not-failure.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded pinned-source experiments; scope in article","pageClass":"execution-facts-article"},"headers":[],"relativePath":"en/engineering/2026-09-15-pause-is-not-failure.md","filePath":"en/engineering/2026-09-15-pause-is-not-failure.md","lastUpdated":1789442662000}'),h={name:"en/engineering/2026-09-15-pause-is-not-failure.md"};function p(l,e,u,g,m,f){const n=t("ArticleCover"),r=t("ArticleTableScroll");return i(),o("div",null,[a(n,{image:"/assets/execution-facts-20260915/pause-is-not-failure.cover-v1.png",kicker:"Open-source engineering · Experiments",title:"Why did pausing work turn into a task failure?",summary:"Pause should mean wait a while. Why did tasks still need intervention after resuming? The problem began when “cannot continue” lost its reason.",version:"2026-09-15",languageHref:"/zh/engineering/2026-09-15-pause-is-not-failure",languageLabel:"中文"}),a(r,{language:"en"}),e[0]||(e[0]=d('<h1 id="why-did-pausing-work-turn-into-a-task-failure" tabindex="-1">Why did pausing work turn into a task failure? <a class="header-anchor" href="#why-did-pausing-work-turn-into-a-task-failure" aria-label="Permalink to &quot;Why did pausing work turn into a task failure?&quot;">​</a></h1><p>After pressing pause and then resume, you would probably expect the original work to return to its queue.</p><p>If tasks instead appear as problems requiring intervention, it can look as though pausing broke them.</p><p>A proposed fix in an AI team-management tool exposed that surprising possibility. <strong>Many things can prevent work from starting. Lose the reason, and a wait can turn into a recorded problem.</strong></p><h2 id="the-same-stop-needs-different-next-steps" tabindex="-1">The same stop needs different next steps <a class="header-anchor" href="#the-same-stop-needs-different-next-steps" aria-label="Permalink to &quot;The same stop needs different next steps&quot;">​</a></h2><p>Paperclip organizes AI agents and tasks. It calls a group containing them a “company”; here, think of that as an AI team.</p><p>In <a href="https://github.com/paperclipai/paperclip/pull/13443" target="_blank" rel="noreferrer">this proposal</a>, MrBlackTongue reports that checks for unfinished work could escalate tasks as budget-blocked while their company was paused. The budget is a spending allowance for a team or agent.</p><p>Both a pause and an exhausted allowance can prevent new work. But they call for different responses. An intentional pause usually means resume later; an exhausted allowance may require adjusting the budget or deciding whether to continue.</p><p>We are building a collaboration system too. This source gave us a precise question to test: how did “wait for now” become “there is a problem to handle”?</p><h2 id="the-reason-existed-before-it-was-discarded" tabindex="-1">The reason existed before it was discarded <a class="header-anchor" href="#the-reason-existed-before-it-was-discarded" aria-label="Permalink to &quot;The reason existed before it was discarded&quot;">​</a></h2><p>The initial check returned a specific reason that work could not start, such as “company paused” or “budget exhausted.”</p><p>The recovery helper kept only a yes/no answer: something was blocking the action, or nothing was. Any block entered the budget-handling branch.</p><p>Imagine forwarding a note that says “paused today; continue tomorrow” as simply “cannot work today.” If someone then fills in “because we ran out of money,” they will choose the wrong response. That analogy describes only the information loss; in the actual program, the discarded information was the cause of an invocation block.</p><p>The candidate carries that cause forward and checks whether the company is paused before processing each task.</p><p>Checking once at the beginning, however, is not enough.</p><h2 id="three-moments-two-very-different-interpretations" tabindex="-1">Three moments, two very different interpretations <a class="header-anchor" href="#three-moments-two-very-different-interpretations" aria-label="Permalink to &quot;Three moments, two very different interpretations&quot;">​</a></h2><p>The company can change while a check is underway. We deliberately arranged this sequence:</p><ol><li>The company is active at the initial check.</li><li>It pauses; a later check observes that pause as the reason work cannot start.</li><li>It resumes before the result is handled.</li></ol><p>Looking up company state at step three returns “active.” But that cannot overturn step two: <strong>the earlier block really was caused by a pause.</strong></p><p>The candidate uses the cause returned by that observation, rather than reconstructing an earlier reason from a later state.</p><p><img src="'+c+'" alt="A later resume cannot rewrite the observed pause cause"></p><p><em>Figure 1. Keep the reason with the check that observed it. Source: controlled timing inputs in paperclip.json, not measurements of live concurrent users.</em></p><h2 id="record-which-branch-the-program-chooses" tabindex="-1">Record which branch the program chooses <a class="header-anchor" href="#record-which-branch-the-program-chooses" aria-label="Permalink to &quot;Record which branch the program chooses&quot;">​</a></h2><p>We used the original budget-checking code and relevant recovery branches. A test program supplied the planned states and recorded whether the code chose to skip or request budget handling. <strong>No task was actually changed in a database, and this was not a full recovery-system test.</strong></p><table tabindex="0"><thead><tr><th>Arranged condition</th><th>Original choice</th><th>Candidate choice</th></tr></thead><tbody><tr><td>Company already paused</td><td>Request budget handling</td><td>Skip for now</td></tr><tr><td>Pause after the initial check</td><td>Request budget handling</td><td>Skip for now</td></tr><tr><td>Resume just after a pause cause is read</td><td>Request budget handling</td><td>Skip using that pause cause</td></tr><tr><td>Active company exceeds its allowance</td><td>Request budget handling</td><td>Still request budget handling</td></tr><tr><td>Agent budget-paused within an active company</td><td>Request budget handling</td><td>Still request budget handling</td></tr><tr><td>Nothing prevents invocation</td><td>Continue to later checks</td><td>Continue to later checks</td></tr><tr><td>Entire company paused for a budget reason</td><td>Request budget handling</td><td>Respect the company pause; skip</td></tr></tbody></table><p>The seven comparisons show that the candidate did not simply turn every problem into waiting. An actual budget block within an active company retained its handling.</p><p>The last row adds a distinction: when the entire company is paused, the candidate respects that overall state instead of escalating its individual tasks during this check.</p><h2 id="after-skipping-when-does-the-system-return" tabindex="-1">After skipping, when does the system return? <a class="header-anchor" href="#after-skipping-when-does-the-system-return" aria-label="Permalink to &quot;After skipping, when does the system return?&quot;">​</a></h2><p>We established that the tested code stopped treating these pause scenarios as budget problems.</p><p>But “skip this time” is not the end of the story. After resume, are the tasks reconsidered promptly? Could eliminating a false problem leave work waiting indefinitely instead? Answering that requires testing the complete recovery process.</p><p>The next question is therefore: <strong>how can a system preserve why it stopped earlier while promptly checking again when conditions change?</strong></p><p>Developers can examine each handoff: was the reason retained, and did handling infer it from state observed at another time? Users need a clear explanation of which tasks are waiting, which require intervention, and why, after they press resume.</p><p>Preserving the reason is a first step toward making a pause understandable and its next steps manageable.</p><details><summary>Versions, scope, and reproduction</summary><p>We pinned predecessor 0e9b24c and candidate 1db5d93. The probe extracts the original getInvocationBlock, budget-block recovery branch, and candidate pause precheck. Database queries return scripted rows; an escalation recorder captures requested handling. Seven scenarios across two versions produced fourteen observations.</p><p>“Request budget handling” means invoking the escalation path, “skip” means skipping the current candidate task, and “continue to later checks” means passing this branch only. None establishes an actual persisted task change or eventual recovery. The causes are company_paused and budget_exhausted.</p><p>We did not run PostgreSQL integration, live concurrent workers, transactions, or the next recovery scan after resume. The author&#39;s reported batch incident is not our sample, and no corresponding CodeFlowMu defect was established.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-15-execution-facts" target="_blank" rel="noreferrer">Source provenance, probes, results, and reproduction instructions</a>.</p></details>',34))])}const k=s(h,[["render",p]]);export{w as __pageData,k as default};
